{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "In healthy subjects, 5-hydroxyrofecoxib, a lactone-containing drug, had absolute oral bioavailability of 14.9% at 10 mg, below the 20% threshold; its high transfer score makes this directly relevant to the query's lactone-rich, polar scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A complex polycyclic macrolide-like compound showed low absolute bioavailability with high oral clearance in a healthy adult, supporting poor oral absorption for a rigid, oxygen-rich macrocycle.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "9-Nitrocamptothecin, a lactone-containing anticancer drug, has very low absolute oral bioavailability in patients, consistent with incomplete absorption of a polar lactone.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "EM574, a polyoxygenated macrolide, has an estimated human oral bioavailability of about 2%, far below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Hydroxysafflor yellow A, a highly polar polyhydroxylated compound, showed low oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Baicalin, a polar glycoside, showed poor oral bioavailability in healthy subjects, supporting the pattern that highly polar, oxygen-rich molecules are poorly absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Erythromycin, a macrolide with multiple hydroxyls, has about 32% absolute oral bioavailability in humans, above the threshold; however, its transfer score is much lower and its scaffold differs from the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C09"],
      "claim": "Ixabepilone, a macrocyclic lactone, had 41.3% absolute oral bioavailability in patients; this is contradictory evidence but has lower transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Zidovudine, a small polar nucleoside, has 60-70% oral bioavailability, but its low transferability limits relevance to the large, rigid, polycyclic query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Idarubicin, a polycyclic anthracycline, has about 29% oral bioavailability; this is contradictory but has low transferability due to different scaffold and transport/physicochemical profile.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (F < 20%) because multiple high-transfer human/clinical analogues with lactone and polyoxygenated scaffolds show low or very low F (5-hydroxyrofecoxib 14-15%, 9-NC very low, EM574 ~2%, HSYA low, baicalin poor), consistent with the query's very low lipophilicity and high polar surface area. Lower-transfer analogues with moderate F (erythromycin, ixabepilone, zidovudine, idarubicin) are less applicable and do not outweigh the high-transfer low-F evidence.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "High-transfer analogues are not exact structural matches; transfer relies on shared lactone/polyoxygenated polarity features.",
    "No data on intestinal permeability, efflux transport, or metabolism for the query.",
    "Contradictory moderate-F analogues have lower transfer scores and different scaffolds, leaving residual uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

